import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose2d_forward(torch::Tensor x,
                                       torch::Tensor w,
                                       c10::optional<torch::Tensor> bias,
                                       int64_t stride_h, int64_t stride_w,
                                       int64_t pad_h, int64_t pad_w,
                                       int64_t dil_h, int64_t dil_w,
                                       int64_t groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_pipeline.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled ConvTranspose2d forward (gather formulation).
// Each block computes a (Threads * PVec) tile of output pixels for
// CcPerBlock output channels of a single group, for one batch item.
// The group's weight slice is staged into shared memory cooperatively.
__device__ __forceinline__ int floor_div_posb(int a, int b) {
  int q = a / b;
  int r = a % b;
  if (r != 0 && a < 0) --q;
  return q;
}
__device__ __forceinline__ int ceil_div_posb(int a, int b) {
  return -floor_div_posb(-a, b);
}
__device__ __forceinline__ int gcd_pos(int a, int b) {
  while (b != 0) {
    int t = a % b;
    a = b;
    b = t;
  }
  return a == 0 ? 1 : a;
}
// Cooperative tiled ConvTranspose2d forward (gather formulation).
// Each block computes a (Threads * PVec) tile of output pixels for
// CcPerBlock output channels of a single group, for one batch item.
// The group's weight slice is staged into shared memory cooperatively.
template <typename T>
__global__ void __launch_bounds__(128, 6) conv_transpose2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int Cin, int H, int Win,
    int Hout, int Wout,
    int KH, int KW,
    int sh, int sw, int ph, int pw, int dh, int dw,
    int CIg, int COg, int Cout,
    int tiles_per_group)
{
  constexpr int Threads    = 128;
  constexpr int PVec       = 4;
  constexpr int CcPerBlock = 8;
  const int tid = threadIdx.x;
  const int n   = blockIdx.z;
  const int g   = blockIdx.y / tiles_per_group;
  const int ct  = blockIdx.y - g * tiles_per_group;
  const int ci_base = g * CIg;
  const int co_rel0 = ct * CcPerBlock;
  const int co_base = g * COg + co_rel0;
  const int P_total = Hout * Wout;
  // Row-aligned spatial tiling: blockIdx.x encodes (output row, column
  // tile), so a block's pixel tile never crosses an output-row boundary.
  // The staged input footprint is therefore always a single row's narrow
  // column range instead of the full input width, shrinking dynamic
  // shared memory enough that occupancy is no longer smem-limited, and
  // every full tile below takes the fast single-row path.
  const int tiles_per_row = (Wout + Threads * PVec - 1) / (Threads * PVec);
  const int ho_b = blockIdx.x / tiles_per_row;
  const int tx_b = blockIdx.x - ho_b * tiles_per_row;
  const int p_block = ho_b * Wout + tx_b * (Threads * PVec);
  // Global tensors as CuTe tensors (per-batch views for X and Y)
  Tensor mX = make_tensor(make_gmem_ptr(X + (int64_t)n * Cin * H * Win),
                          make_shape(Cin, H, Win),
                          make_stride((int64_t)H * Win, (int64_t)Win, Int<1>{}));
  Tensor mW = make_tensor(make_gmem_ptr(W),
                          make_shape(Cin, COg, KH, KW),
                          make_stride((int64_t)COg * KH * KW, (int64_t)KH * KW, (int64_t)KW, Int<1>{}));
  // Shared memory for the group's weight slice: (CIg, KH, KW, CcPerBlock), cc fastest.
  // Keeping the output-channel tile innermost makes the CcPerBlock weights for a
  // given (ci, kh, kw) contiguous, so the inner loop can fetch them with
  // vectorized float4 broadcast loads instead of scalar shared-memory loads.
  extern __shared__ __align__(16) float sW_raw[];
  Tensor sW = make_tensor(make_smem_ptr(sW_raw),
                          make_shape(CIg, KH, KW, Int<CcPerBlock>{}),
                          make_stride((int64_t)KH * KW * CcPerBlock, (int64_t)KW * CcPerBlock, (int64_t)CcPerBlock, Int<1>{}));
  // Block-level input-tile staging: neighboring output pixels gather from
  // heavily overlapping input windows, so stage the union of those windows
  // in shared memory. Each global X element is then loaded once per block
  // with fully coalesced accesses and reused across all threads and taps,
  // instead of being re-fetched from global memory per thread per tap.
  const int kh_span_b = (KH - 1) * dh;
  const int kw_span_b = (KW - 1) * dw;
  const int pA = p_block;
  const int pB = min(p_block + Threads * PVec, (ho_b + 1) * Wout) - 1;
  const int hoA = ho_b;
  const int hoB = ho_b;
  int h_lo_s = ceil_div_posb(hoA + ph - kh_span_b, sh);
  int h_hi_s = floor_div_posb(hoB + ph, sh);
  h_lo_s = h_lo_s < 0 ? 0 : h_lo_s;
  h_hi_s = h_hi_s > (H - 1) ? (H - 1) : h_hi_s;
  int Ht = h_hi_s - h_lo_s + 1;
  if (Ht < 1) { h_lo_s = h_lo_s > (H - 1) ? (H - 1) : h_lo_s; Ht = 1; }
  // Tiles never cross output rows, so the staged column footprint is
  // always this tile's narrow single-row range rather than full Win.
  const int woA = pA - hoA * Wout;
  const int woB = pB - hoB * Wout;
  int w_lo_s = ceil_div_posb(woA + pw - kw_span_b, sw);
  int w_hi_s = floor_div_posb(woB + pw, sw);
  w_lo_s = w_lo_s < 0 ? 0 : w_lo_s;
  w_hi_s = w_hi_s > (Win - 1) ? (Win - 1) : w_hi_s;
  int Wt = w_hi_s - w_lo_s + 1;
  if (Wt < 1) { w_lo_s = w_lo_s > (Win - 1) ? (Win - 1) : w_lo_s; Wt = 1; }
  // Cooperative load of the weight slice
  const int w_total = CIg * CcPerBlock * KH * KW;
  for (int idx = tid; idx < w_total; idx += Threads) {
    int kw  = idx % KW;
    int t1  = idx / KW;
    int kh  = t1 % KH;
    t1     /= KH;
    int cc  = t1 % CcPerBlock;
    int ci  = t1 / CcPerBlock;
    float val = 0.0f;
    if (co_rel0 + cc < COg) {
      val = (float)mW(ci_base + ci, co_rel0 + cc, kh, kw);
    }
    sW(ci, kh, kw, cc) = val;
  }
  // Cooperative, fully coalesced load of the input tile (w fastest),
  // double-buffered with cp.async: the next input-channel chunk's
  // global loads are issued while the current chunk is being consumed,
  // so global-memory latency overlaps the compute loop (pipelined
  // staged loads).
  float* sX_raw = sW_raw + w_total;
  constexpr int CiChunk = 2;
  Tensor sX = make_tensor(make_smem_ptr(sX_raw),
                          make_shape(Int<2>{}, Int<CiChunk>{}, Ht, Wt),
                          make_stride((int64_t)CiChunk * Ht * Wt, (int64_t)Ht * Wt, (int64_t)Wt, Int<1>{}));
  const int n_ci_chunks = (CIg + CiChunk - 1) / CiChunk;
  const int x_total = CiChunk * Ht * Wt;
  // Asynchronous staging of one input-channel chunk into buffer `buf`.
  auto stage_chunk = [&](int chunk, int buf) {
    const int ci0_s = chunk * CiChunk;
    const int nc_s = min(CiChunk, CIg - ci0_s);
    for (int idx = tid; idx < x_total; idx += Threads) {
      const int w  = idx % Wt;
      const int t1 = idx / Wt;
      const int h  = t1 % Ht;
      const int ci = t1 / Ht;
      const int src_ci = min(ci, nc_s - 1);
      const T* src = &mX(ci_base + ci0_s + src_ci, h_lo_s + h, w_lo_s + w);
      float* dst = &sX(buf, ci, h, w);
      // cp.async: the trailing argument is the number of bytes to
      // zero-fill (bytes copied = size - zfill). A valid channel
      // copies all four bytes (zero-fill 0); an invalid tail channel
      // is fully zero-filled (zero-fill 4) without reading global
      // memory, and src_ci is clamped so no out-of-bounds pointer is
      // ever formed for the tail.
      __pipeline_memcpy_async(dst, src, sizeof(float),
                              ci < nc_s ? 0 : sizeof(float));
    }
    __pipeline_commit();
  };
  // Blocked output/spatial tiling: each thread owns PVec consecutive
  // output pixels instead of a Threads-strided set. Consecutive pixels
  // in the same output row share input rows and overlapping input
  // columns, so the gather loop can reuse each global X load across the
  // whole per-thread tile and hoist most per-pixel integer phase math.
  const int p0  = p_block + tid * PVec;
  const int ho0 = ho_b;
  const int wo0 = p0 - ho_b * Wout;
  // Fast path: the whole PVec tile is in-bounds inside the block's row
  // (tiles are row-aligned, so a thread's pixels can never cross rows).
  const bool same_row = (wo0 + PVec <= Wout);
  // Accumulators (initialized with bias if present)
  float acc[CcPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    float bv = 0.0f;
    if (B != nullptr && (co_rel0 + cc) < COg) {
      bv = (float)B[co_base + cc];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = bv;
    }
  }
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  T* __restrict__ Yn = Y + (int64_t)n * (int64_t)Cout * sYc;
  // Strided/dilated transposed convolution has many kernel taps that can
  // never land on a given output phase. Enumerate only the input rows/cols
  // that can contribute: ho = h*sh - ph + kh*dh, so for fixed ho the
  // candidate h range is tiny and the gcd test rejects impossible phases.
  const int gh = gcd_pos(sh, dh);
  const int gw = gcd_pos(sw, dw);
  const int kh_span = (KH - 1) * dh;
  const int kw_span = (KW - 1) * dw;
  // Prologue: asynchronously stage the first input-channel chunk.
  stage_chunk(0, 0);
  for (int chunk = 0; chunk < n_ci_chunks; ++chunk) {
    const int ci0 = chunk * CiChunk;
    const int nc = min(CiChunk, CIg - ci0);
    const int cur = chunk & 1;
    // Prefetch the next chunk, then wait until the current chunk's
    // asynchronous copies have landed before consuming them. The
    // prefetch of chunk+1 therefore overlaps the compute of chunk,
    // hiding global-memory latency behind the shared-memory FMA loop.
    if (chunk + 1 < n_ci_chunks) {
      stage_chunk(chunk + 1, 1 - cur);
      __pipeline_wait_prior(1);
    } else {
      __pipeline_wait_prior(0);
    }
    __syncthreads();
    if (same_row) {
      // ---- Fast path: PVec consecutive pixels inside one output row ----
      // All PVec pixels share the same input-row candidates, and their
      // input-column candidates overlap, so walk the union of the taps:
      // each X element is loaded once per block and reused for every
      // active pixel in the thread's spatial tile.
      const int ah = ho0 + ph;
      const int aw0 = wo0 + pw;
      if ((ah % gh) == 0) {
        int h_lo = ceil_div_posb(ah - kh_span, sh);
        int h_hi = floor_div_posb(ah, sh);
        h_lo = h_lo < 0 ? 0 : h_lo;
        h_hi = h_hi > (H - 1) ? (H - 1) : h_hi;
        // Column phase validity per pixel (aw = aw0 + i).
        bool pok[PVec];
        bool any_phase = false;
        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
          pok[i] = ((aw0 + i) % gw) == 0;
          any_phase = any_phase || pok[i];
        }
        if (h_lo <= h_hi && any_phase) {
          // Union of the per-pixel input-column ranges (monotone in i).
          int w_lo = ceil_div_posb(aw0 - kw_span, sw);
          int w_hi = floor_div_posb(aw0 + (PVec - 1), sw);
          w_lo = w_lo < 0 ? 0 : w_lo;
          w_hi = w_hi > (Win - 1) ? (Win - 1) : w_hi;
          for (int h = h_lo; h <= h_hi; ++h) {
            const int rem_h = ah - h * sh;
            if (rem_h < 0 || rem_h > kh_span) continue;
            if ((rem_h % dh) != 0) continue;
            const int kh = rem_h / dh;
            for (int w = w_lo; w <= w_hi; ++w) {
              const int rem0 = aw0 - w * sw;
              // Pixel i taps this input column at kw = (rem0 + i) / dw.
              int kwv[PVec];
              unsigned mask = 0u;
              #pragma unroll
              for (int i = 0; i < PVec; ++i) {
                const int rem = rem0 + i;
                const bool ok = pok[i] && (rem >= 0) && (rem <= kw_span) &&
                                ((rem % dw) == 0);
                kwv[i] = ok ? (rem / dw) : 0;
                mask |= ok ? (1u << i) : 0u;
              }
              if (mask == 0u) continue;
              for (int ci = 0; ci < nc; ++ci) {
                const float xv = (float)sX(cur, ci, h - h_lo_s, w - w_lo_s);
                #pragma unroll
                for (int i = 0; i < PVec; ++i) {
                  if ((mask & (1u << i)) == 0u) continue;
                  const float4* sWv = reinterpret_cast<const float4*>(&sW(ci0 + ci, kh, kwv[i], 0));
                  const float4 wv_lo = sWv[0];
                  const float4 wv_hi = sWv[1];
                  acc[0][i] = fmaf(xv, wv_lo.x, acc[0][i]);
                  acc[1][i] = fmaf(xv, wv_lo.y, acc[1][i]);
                  acc[2][i] = fmaf(xv, wv_lo.z, acc[2][i]);
                  acc[3][i] = fmaf(xv, wv_lo.w, acc[3][i]);
                  acc[4][i] = fmaf(xv, wv_hi.x, acc[4][i]);
                  acc[5][i] = fmaf(xv, wv_hi.y, acc[5][i]);
                  acc[6][i] = fmaf(xv, wv_hi.z, acc[6][i]);
                  acc[7][i] = fmaf(xv, wv_hi.w, acc[7][i]);
                }
              }
            }
          }
        }
      }
    } else {
      // ---- General path: per-pixel gather (row crossings / tail) ----
      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        const int p = p0 + i;
        const int ho = ho_b;
        const int wo = p - ho * Wout;
        if (wo >= Wout) continue;
        const int ah = ho + ph;
        const int aw = wo + pw;
        if ((ah % gh) != 0 || (aw % gw) != 0) continue;
        int h_lo = ceil_div_posb(ah - kh_span, sh);
        int h_hi = floor_div_posb(ah, sh);
        h_lo = h_lo < 0 ? 0 : h_lo;
        h_hi = h_hi > (H - 1) ? (H - 1) : h_hi;
        if (h_lo > h_hi) continue;
        int w_lo = ceil_div_posb(aw - kw_span, sw);
        int w_hi = floor_div_posb(aw, sw);
        w_lo = w_lo < 0 ? 0 : w_lo;
        w_hi = w_hi > (Win - 1) ? (Win - 1) : w_hi;
        if (w_lo > w_hi) continue;
        for (int h = h_lo; h <= h_hi; ++h) {
          const int rem_h = ah - h * sh;
          if (rem_h < 0 || rem_h > kh_span) continue;
          if ((rem_h % dh) != 0) continue;
          const int kh = rem_h / dh;
          for (int w = w_lo; w <= w_hi; ++w) {
            const int rem_w = aw - w * sw;
            if (rem_w < 0 || rem_w > kw_span) continue;
            if ((rem_w % dw) != 0) continue;
            const int kw = rem_w / dw;
            for (int ci = 0; ci < nc; ++ci) {
              float wv[CcPerBlock];
              const float4* sWv = reinterpret_cast<const float4*>(&sW(ci0 + ci, kh, kw, 0));
              const float4 wv_lo = sWv[0];
              const float4 wv_hi = sWv[1];
              wv[0] = wv_lo.x;
              wv[1] = wv_lo.y;
              wv[2] = wv_lo.z;
              wv[3] = wv_lo.w;
              wv[4] = wv_hi.x;
              wv[5] = wv_hi.y;
              wv[6] = wv_hi.z;
              wv[7] = wv_hi.w;
              const float xv = (float)sX(cur, ci, h - h_lo_s, w - w_lo_s);
              #pragma unroll
              for (int cc = 0; cc < CcPerBlock; ++cc) {
                acc[cc][i] = fmaf(xv, wv[cc], acc[cc][i]);
              }
            }
          }
        }
      }
    }
    __syncthreads();
  }
  // Store results (coalesced along Wout)
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    if ((co_rel0 + cc) >= COg) continue;
    const int64_t co = co_base + cc;
    T* __restrict__ Yc = Yn + co * sYc;
    if (same_row) {
      // Whole tile lands in one output row: consecutive scalar stores
      // that coalesce across the warp into full cache lines.
      T* __restrict__ Yrow = Yc + (int64_t)ho0 * sYh + wo0;
      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        Yrow[i] = (T)acc[cc][i];
      }
    } else {
      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        const int p = p0 + i;
        const int wo = p - ho0 * Wout;
        if (wo >= Wout) continue;
        Yc[(int64_t)ho0 * sYh + wo] = (T)acc[cc][i];
      }
    }
  }
}

torch::Tensor conv_transpose2d_forward(torch::Tensor x,
                                       torch::Tensor w,
                                       c10::optional<torch::Tensor> bias,
                                       int64_t stride_h, int64_t stride_w,
                                       int64_t pad_h, int64_t pad_w,
                                       int64_t dil_h, int64_t dil_w,
                                       int64_t groups) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
              "x and w must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cin, Cout/groups, KH, KW]");
  TORCH_CHECK(groups > 0, "groups must be > 0");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  int64_t N   = x_c.size(0);
  int64_t Cin = x_c.size(1);
  int64_t H   = x_c.size(2);
  int64_t Win = x_c.size(3);

  TORCH_CHECK(w_c.size(0) == Cin, "w.size(0) must equal in_channels");
  TORCH_CHECK(Cin % groups == 0, "in_channels must be divisible by groups");
  int64_t COg  = w_c.size(1);
  int64_t KH   = w_c.size(2);
  int64_t KW   = w_c.size(3);
  int64_t Cout = COg * groups;
  int64_t CIg  = Cin / groups;

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value() && bias.value().defined()) {
    TORCH_CHECK(bias.value().is_cuda(), "bias must be CUDA");
    TORCH_CHECK(bias.value().scalar_type() == at::kFloat, "bias must be float32");
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [out_channels]");
    b_ptr = b_c.data_ptr<float>();
  }

  // ConvTranspose2d output size (output_padding = 0)
  int64_t Hout = (H - 1) * stride_h - 2 * pad_h + dil_h * (KH - 1) + 1;
  int64_t Wout = (Win - 1) * stride_w - 2 * pad_w + dil_w * (KW - 1) + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size");

  auto y = torch::empty({N, Cout, Hout, Wout}, x_c.options());

  constexpr int Threads    = 128;
  constexpr int PVec       = 4;
  constexpr int CcPerBlock = 8;
  constexpr int CiChunk    = 2;

  int tiles_per_group = (int)((COg + CcPerBlock - 1) / CcPerBlock);
  // Row-aligned spatial tiles: blockIdx.x = output_row * tiles_per_row
  // + column_tile, so no block's pixel tile ever crosses an output row.
  int64_t tiles_per_row = (Wout + Threads * PVec - 1) / (Threads * PVec);
  dim3 block(Threads);
  dim3 grid((unsigned)(Hout * tiles_per_row),
            (unsigned)(groups * tiles_per_group),
            (unsigned)N);
  // Shared memory: group weight slice plus the worst-case input tile
  // staged per block. Row-aligned tiles always stage a single output
  // row's input footprint, so the staged width is the tile's narrow
  // column range instead of the full input width, which lifts the
  // shared-memory-imposed occupancy cap for wide outputs.
  int64_t kh_span_h = (KH - 1) * dil_h;
  int64_t kw_span_h = (KW - 1) * dil_w;
  int64_t Ht_max = kh_span_h / stride_h + 2;
  if (Ht_max > H) Ht_max = H;
  int64_t Wt_max = ((int64_t)Threads * PVec - 1 + kw_span_h) / stride_w + 2;
  if (Wt_max > Win) Wt_max = Win;
  size_t smem = ((size_t)CIg * CcPerBlock * KH * KW +
                 (size_t)2 * CiChunk * Ht_max * Wt_max) * sizeof(float);

  static int max_optin_bytes = 0;
  if (max_optin_bytes == 0) {
    int dev = 0;
    cudaError_t err_dev = cudaGetDevice(&dev);
    TORCH_CHECK(err_dev == cudaSuccess, "cudaGetDevice failed: ",
                cudaGetErrorString(err_dev));
    cudaError_t err_attr = cudaDeviceGetAttribute(
        &max_optin_bytes, cudaDevAttrMaxSharedMemoryPerBlockOptin, dev);
    TORCH_CHECK(err_attr == cudaSuccess, "cudaDeviceGetAttribute failed: ",
                cudaGetErrorString(err_attr));
  }
  TORCH_CHECK((int64_t)smem <= (int64_t)max_optin_bytes,
              "Weight tile too large for shared memory: ", smem, " > ",
              max_optin_bytes);
  constexpr size_t kDefaultDynSmem = 48 * 1024;
  if (smem > kDefaultDynSmem) {
    cudaError_t err_set = cudaFuncSetAttribute(
        conv_transpose2d_kernel<float>,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        (int)smem);
    TORCH_CHECK(err_set == cudaSuccess, "cudaFuncSetAttribute failed: ",
                cudaGetErrorString(err_set));
  }

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv_transpose2d_kernel<float><<<grid, block, smem, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)Cin, (int)H, (int)Win,
      (int)Hout, (int)Wout,
      (int)KH, (int)KW,
      (int)stride_h, (int)stride_w, (int)pad_h, (int)pad_w,
      (int)dil_h, (int)dil_w,
      (int)CIg, (int)COg, (int)Cout,
      tiles_per_group);

  auto err = cudaGetLastError();
