  // row's input footprint, so the staged width is the tile's narrow
  // column range instead of the full input width, which lifts the
  // shared-memory-imposed occupancy cap for wide outputs.
  int64_t kh_span_h = (KH - 1) * dil_h;
  int64_t kw_span_h = (KW - 1) * dil_w;
  int64_t Ht_max = kh_span_h / stride_h + 2;
  if (Ht_max > H) Ht_max = H;
  int64_t Wt_max = ((int64_t)Threads * PVec - 1 + kw_span_h) / stride_w + 2;
  if (Wt_max > Win) Wt_max = Win;
